// Visualization for stock data: bubble chart + table
const width = 600;
const height = 520;
const svg = d3.select('#bubble-chart')
  .attr('viewBox', `0 0 ${width} ${height}`);

const tooltip = d3.select('body').append('div')
  .attr('class', 'tooltip');

const formatMarketCap = (value) => {
  if (value == null || isNaN(value)) return 'N/A';
  const fmt = d3.format('.2s');
  let s = fmt(value);
  // Convert to readable units
  s = s.replace('G', 'B');
  s = s.replace('M', 'M');
  s = s.replace('T', 'T');
  return s;
};

d3.csv('data/stock-descriptions.csv').then(rawData => {
  const data = rawData.map(d => ({
    ticker: d.ticker,
    sector: d.sector,
    fullName: d['full name'],
    marketCap: d.marketCap ? +d.marketCap : null,
    country: d.country,
    website: d.website
  }));

  // Deterministic sorting
  data.sort((a, b) => d3.ascending(a.ticker, b.ticker));

  const sectors = Array.from(new Set(data.map(d => d.sector))).sort();
  const color = d3.scaleOrdinal()
    .domain(sectors)
    .range(d3.schemeTableau10);

  const marketCaps = data.filter(d => d.marketCap != null).map(d => d.marketCap);
  const capExtent = d3.extent(marketCaps);
  const radiusScale = d3.scaleSqrt()
    .domain(capExtent)
    .range([12, 40]);

  data.forEach((d, i) => {
    d.radius = d.marketCap != null ? radiusScale(d.marketCap) : 12;
    d.x = width / 2 + (i % 10) * 5; // deterministic initial positions
    d.y = height / 2 + Math.floor(i / 10) * 5;
  });

  // Sector centers in a circle
  const angleStep = (2 * Math.PI) / sectors.length;
  const sectorCenters = new Map();
  sectors.forEach((s, i) => {
    const angle = i * angleStep;
    sectorCenters.set(s, {
      x: width / 2 + Math.cos(angle) * 140,
      y: height / 2 + Math.sin(angle) * 140
    });
  });

  const simulation = d3.forceSimulation(data)
    .force('x', d3.forceX(d => sectorCenters.get(d.sector).x).strength(0.25))
    .force('y', d3.forceY(d => sectorCenters.get(d.sector).y).strength(0.25))
    .force('collide', d3.forceCollide(d => d.radius + 1))
    .stop();

  // Run fixed number of ticks for determinism
  for (let i = 0; i < 250; ++i) simulation.tick();

  const nodes = svg.append('g')
    .selectAll('g')
    .data(data)
    .join('g')
    .attr('class', 'node')
    .attr('transform', d => `translate(${d.x},${d.y})`)
    .on('mouseover', (event, d) => {
      if (d.marketCap == null) return; // no tooltip for ETFs
      tooltip.style('opacity', 1)
        .html(`<strong>${d.ticker}</strong><br>${d.fullName}<br>${d.sector}`);
    })
    .on('mousemove', (event) => {
      tooltip.style('left', (event.pageX + 10) + 'px')
        .style('top', (event.pageY - 28) + 'px');
    })
    .on('mouseout', () => {
      tooltip.style('opacity', 0);
    })
    .on('click', (event, d) => {
      selectTicker(d.ticker);
    });

  nodes.append('circle')
    .attr('r', d => d.radius)
    .attr('fill', d => color(d.sector));

  nodes.append('text')
    .text(d => d.ticker)
    .style('font-size', d => Math.max(8, Math.min(12, d.radius * 0.6)) + 'px');

  // Legend
  const legend = svg.append('g')
    .attr('class', 'legend')
    .attr('transform', 'translate(10,10)');

  const legendItem = legend.selectAll('g')
    .data(sectors)
    .join('g')
    .attr('transform', (d, i) => `translate(0, ${i * 18})`);

  legendItem.append('rect')
    .attr('width', 12)
    .attr('height', 12)
    .attr('fill', d => color(d));

  legendItem.append('text')
    .attr('x', 18)
    .attr('y', 10)
    .text(d => d);

  // Table
  const table = d3.select('#stock-table');
  const tbody = table.select('tbody');

  const rows = tbody.selectAll('tr')
    .data(data)
    .join('tr')
    .on('click', (event, d) => selectTicker(d.ticker));

  rows.append('td').text(d => d.ticker);
  rows.append('td').text(d => d.fullName);
  rows.append('td').text(d => d.sector);
  rows.append('td').text(d => formatMarketCap(d.marketCap));

  // Linking selection
  let selectedTicker = null;
  function selectTicker(ticker) {
    selectedTicker = ticker;
    nodes.classed('selected', d => d.ticker === selectedTicker);
    rows.classed('selected', d => d.ticker === selectedTicker);
  }
});
